/// Computes the factorial of the last decimal digit of `n`.
///
/// The last decimal digit is `n % 10`, which lies between 0 and 9.
/// Since 9! = 362_880 fits well within `u64`, we can safely compute it.
pub fn factorial_of_last_digit(n: u64) -> u64 {
    let last_digit = n % 10;
    let mut fact = 1u64;
    for i in 1..=last_digit {
        fact = fact.saturating_mul(i);
    }
    fact
}

